import{_ as t,o as s,c as d,a3 as a}from"./chunks/framework.B02wg2PO.js";const u=JSON.parse('{"title":"Command Line Interface","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),o={name:"reference/cli.md"};function i(r,e,n,c,l,h){return s(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="command-line-interface" tabindex="-1">Command Line Interface <a class="header-anchor" href="#command-line-interface" aria-label="Permalink to &quot;Command Line Interface&quot;">​</a></h1><p>Saidi ships two executables and a set of npm scripts. The executables are thin launchers: neither parses command-line flags, so everything you configure comes from the environment, <code>config/settings.json</code>, or the Settings UI. This page lists what the code actually reads.</p><h2 id="binaries" tabindex="-1">Binaries <a class="header-anchor" href="#binaries" aria-label="Permalink to &quot;Binaries&quot;">​</a></h2><p><code>package.json</code> declares two entries:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;saidi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./bin/saidi.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;saidi-marketplace&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./bin/saidi-marketplace.js&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="saidi" tabindex="-1"><code>saidi</code> <a class="header-anchor" href="#saidi" aria-label="Permalink to &quot;`saidi`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">saidi</span></span></code></pre></div><p><code>bin/saidi.js</code> is a supervisor. It runs the orchestrator server as a child process, watches it, and relaunches it when the server asks for a fresh boot. It takes <strong>no arguments and no flags</strong> — <code>process.argv</code> is never read.</p><p>What it does on startup:</p><ol><li><code>process.chdir()</code> to the package root, because the server reads <code>.env</code> and <code>client/dist</code> relative to <code>process.cwd()</code> and a global install can be launched from anywhere.</li><li>Resolve the data dir, mirroring <code>src/orchestrator/config.ts</code>: <code>SAIDI_HOME</code> → (if <code>SAIDI_DEV</code>) the package root → <code>~/.saidi</code>.</li><li>Resolve the port for the browser URL: <code>PORT</code> → <code>config/settings.json</code> <code>port</code> → <code>4317</code>. The host follows the same shape: <code>HOST</code> → <code>settings.json</code> <code>host</code> → <code>127.0.0.1</code>.</li><li>Choose the runtime — <code>dist/server.js</code> with plain Node when the bundle exists and <code>SAIDI_DEV</code> is unset, otherwise <code>node --import tsx src/orchestrator/server.ts</code>.</li><li>Spawn the child, and on the first launch only, wait up to 20 s for the port to accept a TCP connection, then open <code>http://localhost:&lt;port&gt;/</code> in the default browser (<code>open</code> on macOS, <code>start</code> on Windows, <code>xdg-open</code> elsewhere). Skipped entirely when <code>SAIDI_DEV</code> is set, because dev serves the UI from Vite on 5317.</li></ol><p>Environment it reads:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th></tr></thead><tbody><tr><td><code>SAIDI_HOME</code></td><td>Data dir override, resolved to an absolute path</td></tr><tr><td><code>SAIDI_DEV</code></td><td>Run from source via tsx, keep state in the package root, skip the browser open</td></tr><tr><td><code>PORT</code></td><td>Port used for the browser URL and the listen probe</td></tr><tr><td><code>HOST</code></td><td>Host used for the listen probe (<code>0.0.0.0</code> probes <code>127.0.0.1</code>)</td></tr></tbody></table><p>Environment it sets on the child:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Value</th></tr></thead><tbody><tr><td><code>SAIDI_SUPERVISED</code></td><td><code>1</code> — tells the server its self-restart path is safe to take</td></tr><tr><td><code>SAIDI_RUNTIME</code></td><td><code>dist</code> or <code>src</code> — tells the server whether <code>npm i -g</code> would replace the running code</td></tr></tbody></table><p>Signals: <code>SIGINT</code> and <code>SIGTERM</code> are forwarded to the child; the supervisor exits once the child does.</p><h3 id="saidi-marketplace" tabindex="-1"><code>saidi-marketplace</code> <a class="header-anchor" href="#saidi-marketplace" aria-label="Permalink to &quot;`saidi-marketplace`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">saidi-marketplace</span></span></code></pre></div><p><code>bin/saidi-marketplace.js</code> runs the standalone hosted-marketplace service. Same shape as <code>saidi</code> but without the supervision: it anchors cwd to the package root, picks <code>dist/marketplace-server.js</code> when it exists and <code>SAIDI_DEV</code> is unset, otherwise <code>node --import tsx src/marketplace/server/index.ts</code>, forwards <code>SIGINT</code> and <code>SIGTERM</code>, and propagates the child&#39;s exit code. No flags are parsed; only <code>SAIDI_DEV</code> is read.</p><h2 id="the-supervisor" tabindex="-1">The supervisor <a class="header-anchor" href="#the-supervisor" aria-label="Permalink to &quot;The supervisor&quot;">​</a></h2><p><code>bin/supervisor.js</code> is not an executable — it is the pure decision module that <code>bin/saidi.js</code> imports. Factoring it out keeps the relaunch rules unit-testable without spawning anything (<code>bin/supervisor.test.ts</code>).</p><p><code>decideRestart(code, restartTimestamps, now, ctx)</code> returns one of four actions:</p><table tabindex="0"><thead><tr><th>Child exit code</th><th>Action</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>75</code> (<code>RESTART_EXIT_CODE</code>)</td><td><code>relaunch</code></td><td>The server asked for a fresh boot (new <code>MONGODB_URI</code>, re-hydrated env, an agent or memory import). The old child fully exits first, so the port is released before the new one binds</td></tr><tr><td><code>76</code> (<code>UPDATE_EXIT_CODE</code>)</td><td><code>update</code></td><td>Install the update, then relaunch</td></tr><tr><td>anything else</td><td><code>exit</code></td><td>Clean stop or crash — propagated, never relaunched</td></tr><tr><td>any, post-update</td><td><code>rollback</code></td><td>A freshly updated child that died before proving itself</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Constant</th><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>MAX_RESTARTS</code></td><td><code>3</code></td><td>Relaunches allowed inside the window</td></tr><tr><td><code>WINDOW_MS</code></td><td><code>10_000</code></td><td>The crash-loop window</td></tr><tr><td><code>HEALTHY_MS</code></td><td><code>60_000</code></td><td>How long an updated child must survive before the rollback net is disarmed</td></tr></tbody></table><p>The update install deliberately happens in the supervisor, between spawns: <code>npm i -g</code> deletes and rewrites the very package directory the server executes from, so doing it in-process would swap the code under a live server. The package installed is <code>github:saeed9321/saidi-agent</code>; a rollback reinstalls <code>github:saeed9321/saidi-agent#v&lt;version&gt;</code>. An install failure (offline, <code>EACCES</code> on a root-owned prefix) is non-fatal and leaves the current version in place.</p><p>The rollback check runs before the crash-loop guard and bypasses it — a broken release that dies instantly would otherwise trip the guard and leave the app down, which is the outage rollback exists to prevent. It is one-shot: if the old version also fails, the exit code propagates normally.</p><h2 id="npm-scripts" tabindex="-1">npm scripts <a class="header-anchor" href="#npm-scripts" aria-label="Permalink to &quot;npm scripts&quot;">​</a></h2><h3 id="running" tabindex="-1">Running <a class="header-anchor" href="#running" aria-label="Permalink to &quot;Running&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Script</th><th>Command</th><th>Notes</th></tr></thead><tbody><tr><td><code>start</code></td><td><code>tsx src/orchestrator/server.ts</code></td><td>Run the orchestrator from source</td></tr><tr><td><code>start:prod</code></td><td><code>node dist/server.js</code></td><td>Run the built bundle</td></tr><tr><td><code>dev</code></td><td><code>concurrently --raw -n server,client</code> over <code>dev:server</code> and <code>dev:client</code></td><td>Both halves with interleaved output</td></tr><tr><td><code>dev:server</code></td><td><code>cross-env tsx watch src/orchestrator/server.ts</code></td><td>Restarts on source change</td></tr><tr><td><code>dev:client</code></td><td><code>npm --prefix client run dev</code></td><td>Vite dev server on port 5317</td></tr><tr><td><code>start:marketplace</code></td><td><code>tsx src/marketplace/server/index.ts</code></td><td>Marketplace service from source</td></tr><tr><td><code>start:marketplace:prod</code></td><td><code>node dist/marketplace-server.js</code></td><td>Marketplace service from the bundle</td></tr></tbody></table><h3 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to &quot;Building&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Script</th><th>Command</th><th>Output</th></tr></thead><tbody><tr><td><code>build</code></td><td><code>build:client</code> then <code>build:server</code></td><td>The normal full build</td></tr><tr><td><code>build:client</code></td><td><code>npm --prefix client run build</code></td><td><code>client/dist/</code></td></tr><tr><td><code>build:server</code></td><td><code>node scripts/build-server.mjs</code></td><td><code>dist/server.js</code></td></tr><tr><td><code>build:sandbox-worker</code></td><td><code>node scripts/build-sandbox-worker.mjs</code></td><td><code>dist/sandbox-worker.js</code></td></tr><tr><td><code>build:marketplace</code></td><td><code>node scripts/build-marketplace.mjs</code></td><td><code>dist/marketplace-server.js</code></td></tr><tr><td><code>build:dist</code></td><td><code>node scripts/build-dist.mjs</code></td><td><code>staging-dist/</code> — the publishable artifact</td></tr><tr><td><code>build:all</code></td><td><code>build</code> then <code>build:dist</code></td><td>Everything, in order</td></tr></tbody></table><h3 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Script</th><th>Command</th><th>Notes</th></tr></thead><tbody><tr><td><code>setup</code></td><td><code>npm install &amp;&amp; npm --prefix client install</code></td><td>Install both dependency trees</td></tr><tr><td><code>prepare</code></td><td><code>npm --prefix client install &amp;&amp; npm run build</code></td><td>npm lifecycle hook — installs the client and builds on install</td></tr><tr><td><code>typecheck</code></td><td><code>tsc --noEmit &amp;&amp; npm --prefix client run typecheck</code></td><td>Server and client, no emit</td></tr><tr><td><code>test</code></td><td><code>cross-env SAIDI_HOME=. node --import tsx --test &lt;files&gt;</code></td><td>The full suite, with the data dir pinned to the repo so tests never touch <code>~/.saidi</code></td></tr><tr><td><code>test:chat</code></td><td><code>node --import tsx --test src/orchestrator/chats/{store,engine}.test.ts</code></td><td>Chat store and engine only</td></tr><tr><td><code>test:migration</code></td><td><code>node --import tsx --test src/orchestrator/legacy-mongo-migration.test.ts</code></td><td>The legacy import path only</td></tr><tr><td><code>vault</code></td><td><code>node scripts/obsidian-vault.mjs</code></td><td>Generate the Obsidian mirror of the memory dir</td></tr><tr><td><code>version</code></td><td><code>node scripts/sync-version.mjs &amp;&amp; git add client/package.json CHANGELOG.md</code></td><td>npm <code>version</code> lifecycle hook — mirrors the root version into <code>client/package.json</code></td></tr></tbody></table><p>Node 20 or newer is required (<code>engines.node: &quot;&gt;=20&quot;</code>). See <a href="/docs/quickstart/installation">Installation</a> for a first run.</p><h2 id="build-scripts" tabindex="-1">Build scripts <a class="header-anchor" href="#build-scripts" aria-label="Permalink to &quot;Build scripts&quot;">​</a></h2><p>All three bundlers use esbuild with the same settings: <code>bundle: true</code>, <code>platform: &quot;node&quot;</code>, <code>format: &quot;esm&quot;</code>, <code>target: &quot;node20&quot;</code>, <code>minify: true</code>, and <code>packages: &quot;external&quot;</code>. Keeping npm packages external means only Saidi&#39;s own first-party source is bundled (and thus hidden), while native modules and the agent CLI the Claude Agent SDK spawns are installed from the registry at the destination and keep working exactly as they do from source.</p><p>Each carries a small resolve plugin that maps relative <code>./foo.js</code> / <code>../bar.js</code> imports to the sibling <code>foo.ts</code> when it exists, because the source uses NodeNext-style <code>.js</code> specifiers that actually point at <code>.ts</code> files.</p><table tabindex="0"><thead><tr><th>Script</th><th>Entry point</th><th>Output</th></tr></thead><tbody><tr><td><code>scripts/build-server.mjs</code></td><td><code>src/orchestrator/server.ts</code></td><td><code>dist/server.js</code></td></tr><tr><td><code>scripts/build-marketplace.mjs</code></td><td><code>src/marketplace/server/index.ts</code></td><td><code>dist/marketplace-server.js</code></td></tr><tr><td><code>scripts/build-sandbox-worker.mjs</code></td><td><code>src/orchestrator/sandbox/worker.ts</code></td><td><code>dist/sandbox-worker.js</code></td></tr></tbody></table><p>The sandbox worker keeps packages external for a second reason: the sandbox image installs <code>@anthropic-ai/claude-agent-sdk</code> from npm so it gets the Linux platform binary the SDK spawns — bundling the host&#39;s build would not run in the container.</p><h3 id="scripts-build-dist-mjs" tabindex="-1"><code>scripts/build-dist.mjs</code> <a class="header-anchor" href="#scripts-build-dist-mjs" aria-label="Permalink to &quot;`scripts/build-dist.mjs`&quot;">​</a></h3><p>Assembles the source-free publishable artifact into <code>staging-dist/</code>. It fails fast if <code>dist/server.js</code> or <code>client/dist/index.html</code> is missing, so run the builds first. The staging tree contains <code>dist/</code>, <code>client/dist/</code>, <code>bin/{saidi.js,supervisor.js}</code>, <code>README.md</code>, <code>CHANGELOG.md</code>, and a minimal <code>package.json</code> carrying runtime dependencies only — no <code>src/</code>, <code>.env</code>, <code>agents/</code>, <code>memory/</code>, or <code>config/</code>. As a guard it walks the finished tree and throws if any <code>.ts</code> or <code>.tsx</code> file leaked in. See <a href="/docs/operations/deployment">Deployment</a> for what to do with the result.</p><h3 id="scripts-obsidian-vault-mjs" tabindex="-1"><code>scripts/obsidian-vault.mjs</code> <a class="header-anchor" href="#scripts-obsidian-vault-mjs" aria-label="Permalink to &quot;`scripts/obsidian-vault.mjs`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span></span></code></pre></div><p>Generates a read-only Obsidian mirror of the memory dir: <code>memory/INDEX.md</code> (a hub note wikilinking every project and agent memory note, with fact counts and last-modified dates) and <code>memory/.obsidian/app.json</code> (ignore filters for <code>runs/</code>, <code>chat/</code>, <code>chat-uploads/</code>, <code>members/</code> and <code>.obsidian/</code>, merged rather than overwritten so settings changed inside Obsidian survive). Nothing is read back — edits made in Obsidian are never synced. It refuses to run when <code>SAIDI_CLOUD=1</code>, because in cloud each org has its own memory dir and there is no single vault. It reads <code>SAIDI_HOME</code> from the environment or, failing that, parses <code>.env</code> itself.</p><h2 id="maintenance-scripts" tabindex="-1">Maintenance scripts <a class="header-anchor" href="#maintenance-scripts" aria-label="Permalink to &quot;Maintenance scripts&quot;">​</a></h2><p>These are not wired into npm scripts; run them directly. Each resolves the Mongo server the same way the app does (<code>MONGODB_URI</code> → <code>memory/secrets.json</code> → localhost) and the database name from <code>SAIDI_CLOUD</code>. Back up MongoDB before any of them writes.</p><h3 id="scripts-cleanup-unscoped-mjs" tabindex="-1"><code>scripts/cleanup-unscoped.mjs</code> <a class="header-anchor" href="#scripts-cleanup-unscoped-mjs" aria-label="Permalink to &quot;`scripts/cleanup-unscoped.mjs`&quot;">​</a></h3><p>Removes DB records that are not scoped to an organization, so a cloud database is cleanly multi-tenant.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/cleanup-unscoped.mjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # dry run — counts only</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/cleanup-unscoped.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # actually delete</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>--yes</code></td><td>Apply the deletions. Without it the script is a dry run</td></tr></tbody></table><p>It deletes orgless <code>AgentDef</code> documents, orgless records in the org-scoped collections (runs, chats, crons, reflexes, activity, memory, credit ledger), and the single local-mode credit wallet keyed <code>default</code>. It keeps the four owner-managed platform documents (settings, secrets, provider-profiles, scan-roots), every record that has an <code>orgId</code>, and all auth records. Idempotent.</p><h3 id="scripts-consolidate-creative-roster-mjs" tabindex="-1"><code>scripts/consolidate-creative-roster.mjs</code> <a class="header-anchor" href="#scripts-consolidate-creative-roster-mjs" aria-label="Permalink to &quot;`scripts/consolidate-creative-roster.mjs`&quot;">​</a></h3><p>A one-shot roster consolidation that updates both the Mongo agent documents and the materialized disk copy — a disk-only cleanup would revert on the next boot, because agent dirs are rebuilt from Mongo.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/consolidate-creative-roster.mjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # dry run</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/consolidate-creative-roster.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # apply</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SAIDI_ORG_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">org</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/consolidate-creative-roster.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag / variable</th><th>Effect</th></tr></thead><tbody><tr><td><code>--yes</code></td><td>Apply; otherwise dry run</td></tr><tr><td><code>SAIDI_ORG_ID</code></td><td>Target org; defaults to <code>local</code></td></tr></tbody></table><p>Restart the server afterwards so it re-materializes the corrected roster.</p><h3 id="scripts-migrate-to-cloud-mjs" tabindex="-1"><code>scripts/migrate-to-cloud.mjs</code> <a class="header-anchor" href="#scripts-migrate-to-cloud-mjs" aria-label="Permalink to &quot;`scripts/migrate-to-cloud.mjs`&quot;">​</a></h3><p>Turns an existing single-user data set into organization #1 of a <code>SAIDI_CLOUD=1</code> deployment.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/migrate-to-cloud.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> you@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --org-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Acme&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Said&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --seats</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--dry-run]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Required</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--email</code></td><td>yes</td><td>—</td><td>Superadmin email (lowercased)</td></tr><tr><td><code>--org-name</code></td><td>yes</td><td>—</td><td>The organization&#39;s name</td></tr><tr><td><code>--name</code></td><td>no</td><td><code>Said</code></td><td>Superadmin display name</td></tr><tr><td><code>--seats</code></td><td>no</td><td><code>5</code></td><td>Seat count, floored at 1</td></tr><tr><td><code>--dry-run</code></td><td>no</td><td>off</td><td>Report without writing</td></tr></tbody></table><p>The password comes from <code>SAIDI_MIGRATE_PASSWORD</code> (10+ characters), so it never lands in shell history. The script creates the user, org and owner membership, backfills <code>orgId</code>/<code>createdBy</code> onto runs, crons, reflexes, activity and the ledger, re-keys the credit wallet from <code>default</code> to the org id, and <strong>moves</strong><code>DATA_DIR/{memory,agents}</code> under <code>DATA_DIR/orgs/&lt;orgId&gt;/</code>. It is idempotent — already-completed steps are detected and skipped.</p><h3 id="scripts-run-baseline-mjs" tabindex="-1"><code>scripts/run-baseline.mjs</code> <a class="header-anchor" href="#scripts-run-baseline-mjs" aria-label="Permalink to &quot;`scripts/run-baseline.mjs`&quot;">​</a></h3><p>Measures execution variance across repeated runs of the same brief: divergence is the headline metric, with cost and wall clock reported as p50/p95 because the interesting movement is in the tail.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-baseline.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drive</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   --briefs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> briefs.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline.jsonl</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-baseline.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analyze</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> current.jsonl</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-baseline.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> before.jsonl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> after.jsonl</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Mode</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>drive</code></td><td>Start each brief <code>--reps</code> times against a running Saidi, poll until settled, then measure</td></tr><tr><td><code>analyze</code></td><td>Compute the same metrics over runs already in the store; spends nothing</td></tr><tr><td><code>compare</code></td><td>Print a before/after table from two JSONL files</td></tr></tbody></table><p><code>analyze</code> is the default when no mode is given.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--briefs &lt;file.json&gt;</code></td><td>—</td><td>Required in <code>drive</code> mode. A JSON array of strings, or of <code>{ brief, project? }</code> objects</td></tr><tr><td><code>--reps &lt;n&gt;</code></td><td><code>3</code></td><td>Repetitions per brief</td></tr><tr><td><code>--out &lt;file&gt;</code></td><td><code>baseline.jsonl</code></td><td>Where rows are written</td></tr><tr><td><code>--base &lt;url&gt;</code></td><td><code>SAIDI_BASE_URL</code> or <code>http://127.0.0.1:4317</code></td><td>Server to drive</td></tr><tr><td><code>--cookie &lt;cookie&gt;</code></td><td><code>SAIDI_COOKIE</code> or empty</td><td>Session cookie; needed in cloud mode, not locally</td></tr><tr><td><code>--timeout &lt;ms&gt;</code></td><td><code>1200000</code> (20 min)</td><td>How long to wait for a run to settle</td></tr><tr><td><code>--poll &lt;ms&gt;</code></td><td><code>5000</code></td><td>Poll interval while waiting</td></tr></tbody></table><p>It talks to the same endpoints you would (<a href="/docs/reference/http-api">HTTP API</a>): <code>POST /api/runs</code>, <code>GET /api/runs</code>, <code>GET /api/runs/:id</code>. A run counts as settled once it reaches <code>done</code>, <code>error</code>, <code>cancelled</code>, <code>awaiting_input</code> or <code>paused</code>.</p><h3 id="scripts-sync-version-mjs" tabindex="-1"><code>scripts/sync-version.mjs</code> <a class="header-anchor" href="#scripts-sync-version-mjs" aria-label="Permalink to &quot;`scripts/sync-version.mjs`&quot;">​</a></h3><p>Mirrors the root <code>package.json</code> version into <code>client/package.json</code> so the client bundle and the server report the same <code>APP_VERSION</code>. Run automatically by the npm <code>version</code> lifecycle hook during <code>npm version &lt;bump&gt;</code>; it takes no arguments.</p>',69)])])}const k=t(o,[["render",i]]);export{u as __pageData,k as default};
